import pytest

from client import fetch_invoices, fetch_orders, fetch_profile


class FlakyGet:
    def __init__(self, failures, exc=ConnectionError):
        self.failures = failures
        self.exc = exc
        self.calls = []

    def __call__(self, url):
        self.calls.append(url)
        if len(self.calls) <= self.failures:
            raise self.exc("boom")
        return {"url": url}


def test_succeeds_after_transient_failures():
    get = FlakyGet(failures=2)
    assert fetch_profile(get, 7) == {"url": "/users/7"}
    assert len(get.calls) == 3


def test_gives_up_after_three_attempts():
    get = FlakyGet(failures=99)
    with pytest.raises(ConnectionError):
        fetch_orders(get, 7)
    assert len(get.calls) == 3


def test_non_transient_errors_propagate_immediately():
    get = FlakyGet(failures=99, exc=TypeError)
    with pytest.raises(TypeError):
        fetch_invoices(get, 7)
    assert len(get.calls) == 1, "only ConnectionError is transient; nothing else may be retried"


def test_each_function_hits_its_own_url():
    get = FlakyGet(failures=0)
    fetch_profile(get, 5)
    fetch_orders(get, 5)
    fetch_invoices(get, 5)
    assert get.calls == ["/users/5", "/users/5/orders", "/users/5/invoices"]

