import functools
import time


def retry(attempts=3):
    """Retry ConnectionError up to `attempts` total calls, then re-raise.
    Any other exception propagates immediately."""

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            tries = 0
            while True:
                tries += 1
                try:
                    return fn(*args, **kwargs)
                except ConnectionError:
                    if tries >= attempts:
                        raise
                    time.sleep(0)

        return wrapper

    return decorator


@retry(attempts=3)
def fetch_profile(get, user_id):
    """get(url) -> dict. Transient ConnectionErrors are retried; the call is
    attempted at most 3 times in total, then the error propagates."""
    return get(f"/users/{user_id}")


@retry(attempts=3)
def fetch_orders(get, user_id):
    """Same retry contract as fetch_profile."""
    return get(f"/users/{user_id}/orders")


